package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.ProjectileKind;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import java.util.Objects;
import org.bukkit.Particle;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.entity.Projectile;
import org.bukkit.entity.Witch;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.event.entity.ProjectileLaunchEvent;

public final class FireWizardBehaviour implements CompiledBehaviour {
    private static final Particle CAMPFIRE_COSY_SMOKE = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:campfire_cosy_smoke");

    private static final Attribute ATTACK_DAMAGE = Registries.entry(RegistryKey.ATTRIBUTE, "minecraft:attack_damage");

    private static final EntityType FIREBALL = Registries.entry(RegistryKey.ENTITY_TYPE, "minecraft:fireball");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final Particle DRIPPING_LAVA = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:dripping_lava");

    private static final ProjectileKind LARGE_FIREBALL = ProjectileKind.LARGE_FIREBALL;

    private final MobContext context;

    private Cooldown cooldown;

    private Cooldown cooldown2;

    public FireWizardBehaviour(MobContext context) {
        this.context = context;
        // node #42 function.cooldown
        this.cooldown = new Cooldown();
        // node #52 function.cooldown
        this.cooldown2 = new Cooldown();
    }

    @Override
    public void onNightEnd() {
        // node #6 mob.night_end
        // node #8 world.spawn_particle
        // node #7 mob.self
        final Witch self = ((Witch) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), CAMPFIRE_COSY_SMOKE, self.getEyeLocation(), 30, 1.5d, 1.0d, 1.5d, null);
        // node #9
    }

    @Override
    public void onProjectileHit(ProjectileHitEvent event) {
        // node #22 event.projectile_hit
        // node #29 flow.branch
        // node #23 event.projectile_hit
        final Entity hitEntity = event.getHitEntity();
        if (!(hitEntity instanceof Player)) return;
        // node #28 flow.branch
        // node #24 mob.self
        final Witch self = ((Witch) this.context.entity());
        // node #25 living_entity.attribute
        final AttributeInstance attribute = self.getAttribute(ATTACK_DAMAGE);
        if (attribute == null) return;
        // node #27 living_entity.damage
        // node #26 cast
        final Player cast = (hitEntity instanceof Player ? (Player) hitEntity : null);
        cast.damage(attribute.getValue(), self);
        // node #30
    }

    @Override
    public void onProjectileShoot(ProjectileLaunchEvent event) {
        // node #37 event.projectile_shoot
        // node #39 flow.branch
        if (Objects.equals(event.getEntityType(), FIREBALL)) return;
        // node #38 cancellable.mutate
        event.setCancelled(true);
        // node #40
    }

    @Override
    public void onTick() {
        // node #58 mob.tick
        // node #62 flow.branch
        // node #59 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(250.0d));
        if (cooldown) {
            // node #61 world.spawn_particle
            // node #60 mob.self
            final Witch self = ((Witch) this.context.entity());
            BukkitRuntime.particles(this.context, self.getWorld(), DRIPPING_LAVA, self.getEyeLocation(), 5, 1.5d, 1.0d, 1.5d, null);
        }
        // node #68 flow.branch
        // node #63 mob.self
        final Witch self = ((Witch) this.context.entity());
        // node #64 mob.read
        final LivingEntity target = self.getTarget();
        if (target == null) return;
        // node #67 flow.branch
        // node #65 function.cooldown
        final boolean cooldown2 = this.cooldown2.ready(MILLISECONDS.toMillis(5000.0d));
        if (!cooldown2) return;
        // node #66 living_entity.launch_projectile
        final Projectile projectile = BukkitRuntime.launchAt(self, target, LARGE_FIREBALL, 4.0d);
        // node #69
    }
}
